package com.muxigame.city;
import java.nio.file.*;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

/** Independent original cohorts, not a reset/revival or extension of the live village. */
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsLongRun {
 static void exercise(GameTestHelper h,int pairs,int days,String file){int scale=Integer.getInteger("city.audit.scale",0);if(scale>0&&pairs!=1){h.succeed();return;}if(scale>0){if(scale!=100&&scale!=200&&scale!=400)throw new IllegalArgumentException("Explicit cohort must be100,200or400");pairs=scale/100;}days=Integer.getInteger("city.audit.days",30);int merchants=Integer.getInteger("city.audit.merchants",3);file=System.getProperty("city.audit.tag","ratio3")+"-"+(pairs*100)+"-m"+merchants+"-"+days+".json";try(var f=new CityTestsScale.Fixture(h,pairs,merchants)){for(var c:f.towns)CityModel.configure(f.s,c,f.t.state.towns.get(c.id).urban);if(merchants==3)try{Files.writeString(Path.of("ratio3-"+(pairs*100)+"-setup.json"),CityEconomy.JSON.toJson(f.setup()));}catch(java.io.IOException ex){throw new IllegalStateException(ex);}int farmEnd=Integer.getInteger("city.audit.farmEnd",14);if(farmEnd<7||farmEnd>18)throw new IllegalArgumentException("Farm end must be 7..18");for(var c:f.towns)if(f.t.state.towns.get(c.id).urban)for(var p:f.r.state.people.values())if(p.role==RuralRules.Role.FARMER&&f.r.state.families.get(p.family).city.equals(c.id))WorkHours.config(f.s,p.id).end=farmEnd;try{Files.writeString(Path.of("cause-trial-setup.json"),CityEconomy.JSON.toJson(f.setup()));}catch(java.io.IOException ex){throw new IllegalStateException(ex);}var materials=materialScore(f);var result=f.run(days);result.put("urbanFarmEnd",farmEnd);var residual=materialScore(f);residual.replaceAll((key,value)->value-materials.getOrDefault(key,0L));result.put("materialResidual",residual);result.put("spoiledGrain",FoodDecay.grain(f.s));result.put("spoiledMeat",FoodDecay.meat(f.s));result.put("relief",f.t.state.relief);result.put("totalHarvest",f.t.harvested(f.s));result.put("totalEaten",f.t.eaten(f.s));result.put("totalMeatProduced",f.t.meatProduced(f.s));result.put("totalMeatEaten",f.t.meatEaten(f.s));result.put("version","0.10.13");result.put("auditScaleOverride",scale);result.put("days",days);result.put("reliefImplemented",true);result.put("ownerFoodDraws",f.t.state.businesses.values().stream().mapToLong(b->b.foodDrawn).sum());result.put("directGrain",f.t.state.directGrain);result.put("reverseGrain",f.t.state.reverseGrain);result.put("routeMeat",f.t.state.routeMeat);result.put("continuingBusinessKinds",f.t.state.businesses.values().stream().filter(b->f.t.usable(f.s,b)).collect(java.util.stream.Collectors.groupingBy(b->b.kind,java.util.stream.Collectors.counting())));try{Files.writeString(Path.of(file),CityEconomy.JSON.toJson(result));}catch(java.io.IOException ex){throw new IllegalStateException(ex);}h.assertTrue(residual.values().stream().allMatch(v->v==0),"Supplied, recovered and consumed building materials conserve across the whole independent run");var reloaded=CityData.load(CityData.get(f.s).save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());var reloadedFarm=CityMaintenance.load(f.m.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(reloadedFarm.state.cities.keySet().equals(f.m.state.cities.keySet())&&reloadedFarm.state.cities.entrySet().stream().allMatch(e->e.getValue().baseline.equals(f.m.state.cities.get(e.getKey()).baseline)),"Farm registry survives strict save/reload independently of city registration");h.assertTrue(reloaded.cities.size()==f.towns.size(),"Long-run job changes still save/reload under strict city validation");h.assertTrue(f.conserved,"Every day must audit actual money issue/retirement, grain, meat and goods; economic attrition is reported separately");h.assertTrue(f.r.state.boxes.values().stream().allMatch(b->b.stock.wheat+b.stock.bread+RuralMeat.total(List.of(b.stock))<=10),"Long run retains actual private food caps");}h.succeed();}
 static Map<String,Long> materialScore(CityTestsScale.Fixture f){var out=new TreeMap<String,Long>();for(var c:f.towns)for(String item:CityMaterialCatalog.auditedItems()){var market=c.housing.market.get(item);long stock=c.works.resources.getOrDefault(item,0)+(market==null?0:market.stock);for(var h:c.housing.houses.values())stock+=h.materials.getOrDefault(item,0);out.put(c.id+"/"+item,stock+c.works.materialsConsumed.getOrDefault(item,0L)-c.works.recovered.getOrDefault(item,0L)-c.works.crafted.getOrDefault(item,0L)-(market==null?0:market.supplied)-c.housing.imported.getOrDefault(item,0L)+c.housing.exported.getOrDefault(item,0L));}return out;}
 @GameTest(template="empty",timeoutTicks=200) public static void hundredResidentsExtendedDataAudit(GameTestHelper h){exercise(h,1,500,"overnight110-100-500.json");}
 @GameTest(template="empty",timeoutTicks=200) public static void twoIndependentPairsExtendedDataAudit(GameTestHelper h){exercise(h,2,500,"overnight110-200-500.json");}
}
